import java.util.Scanner;

public class Main {
    static long[] b = new long[20];

    static long solve(long value, long level) {
        long quotient = value / b[(int) level];
        value %= b[(int) level];
        if (value == 0)
            return quotient * level;
        else
            return quotient * level + Math.min(solve(value, level - 1),
                    level + solve(b[(int) level] - value, level - 1));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 1; i <= 17; ++i)
            b[i] = b[i - 1] * 10 + 1;
        long n = sc.nextLong();
        long digit_count = 0, temp_input = n;
        while (temp_input != 0) {
            temp_input /= 10;
            ++digit_count;
        }
        System.out.println(solve(n, digit_count + 2));
        sc.close();
    }
}
